            <section class="dashboard-card"><div class="flex items-center justify-between"><div><h2 class="text-lg font-black text-slate-950">Automation & Grandfather–Father–Son retention</h2><p class="mt-1 text-sm text-slate-500">Keep useful daily, weekly, monthly, and yearly recovery points automatically.</p></div><span class="rounded-full px-3 py-1 text-xs font-black {{ $schedule->enabled ? 'bg-emerald-50 text-emerald-700' : 'bg-slate-100 text-slate-600' }}">{{ $schedule->enabled ? 'Enabled' : 'Manual only' }}</span></div>@if($permissions['backup.configure'])<form method="POST" action="{{ route('backups.schedule.update') }}" class="mt-6 space-y-6">@csrf @method('PUT')<div class="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><label class="text-xs font-bold text-slate-600">Backup type<select name="backup_type" class="mt-1.5 w-full rounded-lg border-slate-200 text-sm">@foreach(['full','database','files'] as $type)<option value="{{ $type }}" @selected($schedule->backup_type === $type)>{{ Str::headline($type) }}</option>@endforeach</select></label><label class="text-xs font-bold text-slate-600">Frequency<select name="frequency" class="mt-1.5 w-full rounded-lg border-slate-200 text-sm">@foreach(['manual','daily','weekly','monthly','custom'] as $frequency)<option value="{{ $frequency }}" @selected($schedule->frequency === $frequency)>{{ Str::headline($frequency) }}</option>@endforeach</select></label><label class="text-xs font-bold text-slate-600">Run time<input type="time" name="run_at" value="{{ Str::substr((string)$schedule->run_at,0,5) }}" class="mt-1.5 w-full rounded-lg border-slate-200 text-sm"></label><label class="flex items-center gap-3 self-end rounded-lg border border-slate-200 p-3 text-sm font-bold text-slate-700"><input type="checkbox" name="enabled" value="1" @checked($schedule->enabled) class="rounded text-violet-600">Enable automatic backups</label></div><fieldset><legend class="text-xs font-bold text-slate-600">Custom days</legend><div class="mt-2 flex flex-wrap gap-2">@foreach(['monday','tuesday','wednesday','thursday','friday','saturday','sunday'] as $day)<label class="rounded-lg border border-slate-200 px-3 py-2 text-xs font-semibold"><input type="checkbox" name="days[]" value="{{ $day }}" @checked(in_array($day,$schedule->days ?? [],true)) class="mr-1 rounded text-violet-600">{{ Str::limit(Str::headline($day),3,'') }}</label>@endforeach</div></fieldset><div class="grid gap-4 md:grid-cols-4">@foreach(['keep_daily'=>'Daily','keep_weekly'=>'Weekly','keep_monthly'=>'Monthly','keep_yearly'=>'Yearly'] as $field=>$label)<label class="text-xs font-bold text-slate-600">Keep {{ $label }}<input type="number" min="0" name="{{ $field }}" value="{{ $schedule->{$field} }}" class="mt-1.5 w-full rounded-lg border-slate-200 text-sm"></label>@endforeach</div>@if($destinations->isNotEmpty())<fieldset><legend class="text-xs font-bold text-slate-600">Automatic copy destinations</legend><div class="mt-2 grid gap-2 md:grid-cols-2">@foreach($destinations as $destination)<label class="flex items-center gap-2 rounded-lg border border-slate-200 p-3 text-sm"><input type="checkbox" name="destination_ids[]" value="{{ $destination->id }}" @checked(in_array($destination->id,$schedule->destination_ids ?? [],true)) class="rounded text-violet-600">{{ $destination->name }}</label>@endforeach</div></fieldset>@endif<button class="rounded-xl bg-violet-600 px-5 py-3 text-sm font-black text-white">Save automation policy</button></form>@endif</section>
