    @push('scripts')<script>
        function backupCenter(){return{destinationDriver:'local',uploading:false,uploadProgress:0,uploadMessage:'Waiting',async uploadBackup(){const file=this.$refs.backupFile?.files?.[0];if(!file)return alert('Choose an .ecbak backup package.');if(!file.name.toLowerCase().endsWith('.ecbak'))return alert('Only .ecbak packages are accepted.');this.uploading=true;const chunkSize=10*1024*1024,key='ecclesia-backup-upload:'+file.name+':'+file.size;try{let state=JSON.parse(localStorage.getItem(key)||'null');if(!state){const response=await fetch(@js(route('backups.uploads.start')),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({filename:file.name,total_size:file.size,chunk_size:chunkSize})});if(!response.ok)throw new Error('Could not start upload');state=await response.json();localStorage.setItem(key,JSON.stringify(state));}const statusUrl=@js(url('administration/backups/uploads'))+'/'+state.id;let status=await fetch(statusUrl,{headers:{Accept:'application/json'}}).then(r=>r.json()),received=new Set(status.received_chunks||[]),total=Math.ceil(file.size/chunkSize);for(let index=0;index<total;index++){if(received.has(index))continue;this.uploadMessage='Uploading chunk '+(index+1)+' of '+total;const body=new FormData();body.append('index',index);body.append('chunk',file.slice(index*chunkSize,Math.min(file.size,(index+1)*chunkSize)),file.name+'.part');const response=await fetch(statusUrl+'/chunks',{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content,'Accept':'application/json'},body});if(!response.ok)throw new Error('Chunk '+(index+1)+' failed');received.add(index);this.uploadProgress=Math.floor(received.size/total*100);}this.uploadMessage='Assembling and checking size';const complete=await fetch(statusUrl+'/complete',{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content,'Accept':'application/json'}});if(!complete.ok)throw new Error('Could not assemble backup');localStorage.removeItem(key);this.uploadProgress=100;this.uploadMessage='Upload complete';location.href=@js(route('backups.index',['tab'=>'restore']));}catch(error){this.uploadMessage=error.message+' — reselect the same file to resume.';}finally{this.uploading=false;}}}}
        document.querySelectorAll('[data-backup-row]').forEach(row=>{const poll=async()=>{try{const data=await fetch(row.dataset.statusUrl,{headers:{Accept:'application/json'}}).then(r=>r.json());row.querySelector('[data-backup-status]').textContent=data.status.replaceAll('_',' ');row.querySelector('[data-backup-progress]').style.width=data.progress+'%';row.querySelector('[data-backup-stage]').textContent=data.stage.replaceAll('_',' ')+' · '+data.progress+'%';if(['queued','running'].includes(data.status))setTimeout(poll,3000);}catch{setTimeout(poll,10000)}};if(['Queued','Running'].includes(row.querySelector('[data-backup-status]').textContent.trim()))poll();});
    </script>@endpush
